Would it be cleaner to have a `colorize()` or `forceColorize()` method that just does

    void PacketListRecord::colorize(capture_file *cap_file, bool colorized)
    {
        // packet_list_store.c:packet_list_get_value
        Q_ASSERT(fdata_);

        if (!cap_file) {
            return;
        }

        bool dissect_color = ( colorized && !colorized_ ) || ( color_ver_ != rows_color_ver_ );
        if (data_ver_ != col_data_ver_ || dissect_color) {
            dissect(cap_file, dissect_color);
        }
    }

